/bin/bash -lc "python3 - <<'PY'
import requests, re
base='https://ftp.1000genomes.ebi.ac.uk/vol1/ftp/data_collections/1000G_2504_high_coverage/'
for path in ['', 'working/', 'working/20190425_NYGC_GATK/', 'working/20201028_3202_phased/', 'release/']:
    u=base+path
    r=requests.get(u, timeout=30)
    print('\\nURL',u,r.status_code)
    if r.ok:
        for m in re.findall(r'href=\"(["'^"]+)"'"', r.text):
            if 'chr22' in m.lower() or 'vcf' in m.lower() or m.endswith('/'):
                print(m)
PY"

/bin/bash -lc "python3 - <<'PY'
import requests, re
base='https://ftp.1000genomes.ebi.ac.uk/vol1/ftp/data_collections/1000G_2504_high_coverage/'
for path in ['', 'working/', 'working/20190425_NYGC_GATK/', 'working/20201028_3202_phased/', 'release/']:
    u=base+path
    r=requests.get(u, timeout=30)
    print('\\nURL',u,r.status_code)
    if r.ok:
        for m in re.findall(r'href=\"(["'^"]+)"'"', r.text):
            if 'chr22' in m.lower() or 'vcf' in m.lower() or m.endswith('/'):
                print(m)
PY"

